This code was copy/pasted from getMessage() above.

Which is the same function that was called in redfish-core/src/event_log.cpp on line 112.

You need to refactor that code out into:

struct MessageId {
std::string RegistryName;
std::string MajorVersion;
std::string MinorVersion;
std::string MessageKey;
};

MessageId getMessageComponents(std::string_view messageId);

Then from the calling code we would do

MessageId msg = getMessageComponents(messageId);
Registry* reg = getRegistryMessagesFromPrefix(msg.RegistryName);
Message* msg = getMessageFromRegistry(messageKey,reg);

// Use the registry version to construct the components.
json["MessageId"] = std::format("{}.{}.{}.{}", reg.Prefix, reg.MajorVersion, reg.MinorVerion, msg.id);
